// Wait until all Apify async runs complete, then merge ALL sources into one list
const APIFY_TOKEN = 'APIFY_TOKEN';

// Get run IDs from the Apify trigger nodes
const liRun    = $('Start LinkedIn Scraper').first()?.json?.data?.id   || null;
const indRun   = $('Start Indeed Scraper').first()?.json?.data?.id    || null;
const diceRun  = $('Start Dice Scraper').first()?.json?.data?.id      || null;

async function runStatus(runId) {
  if (!runId) return { done: true, datasetId: null };
  const r = await fetch(`https://api.apify.com/v2/actor-runs/${runId}?token=${APIFY_TOKEN}`);
  const j = await r.json();
  const s = j?.data?.status || 'UNKNOWN';
  return { done: s === 'SUCCEEDED' || s === 'FAILED', datasetId: j?.data?.defaultDatasetId || null };
}

async function fetchDataset(datasetId, sourceName) {
  if (!datasetId) return [];
  const r = await fetch(`https://api.apify.com/v2/datasets/${datasetId}/items?token=${APIFY_TOKEN}&clean=true&format=json`);
  const arr = await r.json();
  return Array.isArray(arr) ? arr.map(i => ({ ...i, _src: sourceName })) : [];
}

// Check statuses
const [liStatus, indStatus, diceStatus] = await Promise.all([
  runStatus(liRun), runStatus(indRun), runStatus(diceRun)
]);

// If any Apify run is still running, signal retry
if (!liStatus.done || !indStatus.done || !diceStatus.done) {
  return [{ json: { _retry: true } }];
}

// Fetch Apify results
const [liItems, indItems, diceItems] = await Promise.all([
  fetchDataset(liStatus.datasetId, 'linkedin'),
  fetchDataset(indStatus.datasetId, 'indeed'),
  fetchDataset(diceStatus.datasetId, 'dice')
]);

// Pull synchronous source results
const serpRaw     = $('Google Jobs via SerpAPI').first()?.json?.jobs_results  || [];
const remRaw      = $('Remotive API').first()?.json?.jobs                     || [];
const arbRaw      = $('Arbeitnow API').first()?.json?.data                    || [];
const jobicyRaw   = $('Jobicy API').first()?.json?.jobs                       || [];
const wwrDevRaw   = $('WWR DevOps RSS').all()?.map(i => i.json)               || [];
const wwrProgRaw  = $('WWR Programming RSS').all()?.map(i => i.json)          || [];

const serpItems  = Array.isArray(serpRaw)  ? serpRaw.map(i  => ({ ...i,  _src: 'google_jobs' })) : [];
const remItems   = Array.isArray(remRaw)   ? remRaw.map(i   => ({ ...i,  _src: 'remotive'    })) : [];
const arbItems   = Array.isArray(arbRaw)   ? arbRaw.map(i   => ({ ...i,  _src: 'arbeitnow'   })) : [];
const jobicyItems= Array.isArray(jobicyRaw)? jobicyRaw.map(i=> ({ ...i,  _src: 'jobicy'      })) : [];
const wwrDev     = Array.isArray(wwrDevRaw)? wwrDevRaw.map(i=> ({ ...i,  _src: 'wwr'         })) : [];
const wwrProg    = Array.isArray(wwrProgRaw)?wwrProgRaw.map(i=>({ ...i,  _src: 'wwr'         })) : [];

const all = [...liItems, ...indItems, ...diceItems, ...serpItems, ...remItems, ...arbItems, ...jobicyItems, ...wwrDev, ...wwrProg];

if (all.length === 0) return [{ json: { _empty: true } }];
return all.map(item => ({ json: item }));

// Normalise schema + deduplicate + hard remote filter
const REMOTE_SIGNALS = [
  'remote','work from home','wfh','fully remote','100% remote',
  'anywhere','worldwide','distributed','telecommute','virtual',
  'location independent','global remote','no office'
];

// Build set of already-applied URLs from the sheet
const appliedUrls = new Set(
  ($('Load Already-Applied URLs').all() || [])
    .map(i => (i.json['Target URL'] || i.json.targetUrl || '').trim())
    .filter(Boolean)
);

const sessionSeen = new Set();
const results = [];

for (const item of $input.all()) {
  const d = item.json;
  if (d._retry || d._empty) continue;

  const src = d._src || 'unknown';
  let title = '', company = '', location = '', description = '', applyUrl = '', salary = '';

  // Normalise by source
  if (src === 'linkedin') {
    title = d.title; company = d.companyName; location = d.location;
    description = d.descriptionText || d.description || '';
    applyUrl = d.applyUrl || d.url || '';

  } else if (src === 'indeed') {
    title = d.title || d.jobTitle; company = d.company || d.employer || d.companyName;
    location = d.location || d.jobLocation;
    description = d.description || d.jobDescription || '';
    applyUrl = d.url || d.jobUrl || '';

  } else if (src === 'dice') {
    title = d.title; company = d.companyName || d.company;
    location = d.location || 'Remote';
    description = d.descriptionFragment || d.description || '';
    applyUrl = d.applyUrl || d.detailUrl || d.url || '';

  } else if (src === 'google_jobs') {
    title = d.title; company = d.company_name;
    location = d.location;
    description = d.description || (d.detected_extensions ? JSON.stringify(d.detected_extensions) : '') || '';
    applyUrl = (d.related_links && d.related_links[0] && d.related_links[0].link) || d.share_link || '';

  } else if (src === 'remotive') {
    title = d.title; company = d.company_name;
    location = d.candidate_required_location || 'Remote';
    description = d.description || ''; applyUrl = d.url || ''; salary = d.salary || '';

  } else if (src === 'arbeitnow') {
    title = d.title; company = d.company_name;
    location = d.location || 'Remote';
    description = d.description || ''; applyUrl = d.url || '';

  } else if (src === 'jobicy') {
    title = d.jobTitle; company = d.companyName;
    location = d.jobGeo || 'Worldwide';
    description = d.jobExcerpt || d.jobDescription || ''; applyUrl = d.url || '';

  } else if (src === 'wwr') {
    title = d.title; company = d.creator || d.author || '';
    location = 'Remote';
    description = d.contentSnippet || d.content || ''; applyUrl = d.link || d.guid || '';

  } else {
    title = d.title || d.jobTitle; company = d.company || d.companyName;
    location = d.location || 'Remote';
    description = d.description || ''; applyUrl = d.url || d.applyUrl || '';
  }

  // Skip incomplete records
  if (!title || !applyUrl) continue;

  // REMOTE HARD FILTER
  const searchable = (title + ' ' + location + ' ' + description).toLowerCase();
  const isRemote = REMOTE_SIGNALS.some(s => searchable.includes(s));
  if (!isRemote) continue;

  // DEDUPLICATION
  const urlKey = applyUrl.trim();
  if (appliedUrls.has(urlKey) || sessionSeen.has(urlKey)) continue;
  sessionSeen.add(urlKey);

  results.push({
    json: {
      title:       (title   || '').trim().substring(0, 200),
      company:     (company || '').trim().substring(0, 200),
      location:    (location|| 'Remote').trim(),
      description: (description || '').replace(/<[^>]+>/g, ' ').trim().substring(0, 3500),
      applyUrl:    urlKey,
      source:      src,
      salary:      (salary || '').trim()
    }
  });
}

return results.length > 0 ? results : [{ json: { _empty: true } }];

