// Parse Claude API response safely
const item   = $input.first();
const raw    = item.json;
const jobData = $('Normalise + Dedup + Remote Filter').item?.json || {};

// Claude API shape: raw.content[0].text
let text = '';
if (Array.isArray(raw.content) && raw.content[0]?.text) {
  text = raw.content[0].text;
} else if (typeof raw.text === 'string') {
  text = raw.text;
} else {
  text = JSON.stringify(raw);
}

// Strip accidental markdown fences
text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  // Fallback — try to extract JSON with regex
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (_) {}
  }
  if (!parsed.score) {
    parsed = { score: 0, justification: 'Parse failed: ' + e.message, isEasyApply: false, atsKeywords: [], missingSkills: [], estimatedSalaryUSD: null, remoteVerified: false, coverLetterParagraph: '', _error: true };
  }
}

return [{ json: {
  // Job fields
  title:                jobData.title                || '',
  company:              jobData.company              || '',
  location:             jobData.location             || '',
  description:          jobData.description          || '',
  applyUrl:             jobData.applyUrl             || '',
  source:               jobData.source               || '',
  salary:               jobData.salary               || '',
  // AI fields
  score:                typeof parsed.score === 'number' ? parsed.score : 0,
  justification:        typeof parsed.justification  === 'string' ? parsed.justification : '',
  isEasyApply:          parsed.isEasyApply           === true,
  atsKeywords:          Array.isArray(parsed.atsKeywords)   ? parsed.atsKeywords  : [],
  missingSkills:        Array.isArray(parsed.missingSkills) ? parsed.missingSkills : [],
  estimatedSalaryUSD:   typeof parsed.estimatedSalaryUSD === 'number' ? parsed.estimatedSalaryUSD : null,
  remoteVerified:       parsed.remoteVerified        === true,
  coverLetterParagraph: typeof parsed.coverLetterParagraph === 'string' ? parsed.coverLetterParagraph : '',
  _aiError:             parsed._error                || false
}}];

